ALTER TABLE public.account_access ADD COLUMN approved boolean NOT NULL DEFAULT false;
ALTER TABLE public.account_access_audit ADD COLUMN approved boolean;
UPDATE public.account_access a SET approved=true FROM auth.users u WHERE a.user_id=u.id AND lower(u.email)='randrianasolonirinaf@gmail.com' AND u.email_confirmed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u.id AND r.role='admin');
CREATE OR REPLACE FUNCTION public.account_session_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_access a WHERE a.user_id=auth.uid() AND a.approved AND NOT a.blocked AND (a.revoked_before IS NULL OR EXISTS(SELECT 1 FROM auth.sessions s WHERE s.user_id=a.user_id AND s.id=(auth.jwt()->>'session_id')::uuid AND s.created_at>a.revoked_before) OR ((auth.jwt()->>'session_id') IS NULL AND to_timestamp((auth.jwt()->>'iat')::double precision)>a.revoked_before))); $$;
CREATE OR REPLACE FUNCTION public.initialize_account_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.account_access(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; IF lower(NEW.email)='randrianasolonirinaf@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; UPDATE public.account_access SET approved=true WHERE user_id=NEW.id; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.set_account_access(target uuid, should_block boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous boolean; was_approved boolean; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator required'; END IF; IF target=auth.uid() THEN RAISE EXCEPTION 'Cannot modify own access'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target AND role='admin') THEN RAISE EXCEPTION 'Administrator access protected'; END IF; SELECT blocked,approved INTO previous,was_approved FROM public.account_access WHERE user_id=target FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Account not found'; END IF; IF NOT should_block AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=target AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Email confirmation required'; END IF; IF previous IS DISTINCT FROM should_block OR (NOT should_block AND NOT was_approved) THEN UPDATE public.account_access SET blocked=should_block, approved=CASE WHEN should_block THEN approved ELSE true END, revoked_before=CASE WHEN should_block THEN now() ELSE revoked_before END, updated_at=now() WHERE user_id=target; INSERT INTO public.account_access_audit(target_id,actor_id,blocked,approved) VALUES(target,auth.uid(),should_block,CASE WHEN should_block THEN was_approved ELSE true END); END IF; END; $$;